'use strict';
const $=id=>document.getElementById(id), panel=$('panel'), dialog=$('box'), main=$('main');
const menu={studio:'Studio Guru',home:'Home',karakter:'Karakter',skin:'Koleksi Skin',map:'Map',arena:'Lobi Multiplayer',quest:'Quest & Achievement'};
let spots=[18,50,82], user=null,pos=18;
function message(s,bad=false){const el=$('notice');if(el){el.textContent=s;el.className=bad?'warn notice':'success notice'}}
function btn(label,action,cls=''){const b=document.createElement('button');b.type='button';b.textContent=label;b.className=cls;b.onclick=action;return b}
function heading(tag,s){const h=document.createElement(tag);h.textContent=s;return h}
function portrait(i){const c=document.createElement('canvas');c.width=22;c.height=26;sprite(c,i);return c}
function show(title){panel.replaceChildren();let h=heading('h2',title);h.id='dialogTitle';panel.append(h);if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function view(){const route=location.hash.slice(1);return user&&(route!=='studio'||isTeacher)&&Object.hasOwn(menu,route)?route:'home'}
function go(key){if(location.hash==='#'+key)render();else location.hash=key}
function render(){stopArena();const current=view();$('nav').replaceChildren();for(const [key,label] of Object.entries(menu)){if(key==='studio'&&!isTeacher)continue;let b=btn(label,()=>go(key),key===current?'active':'');b.disabled=!user&&key!=='home';if(key===current)b.setAttribute('aria-current','page');$('nav').append(b)}
 $('playerInfo').textContent=user?user.name+' · ✦ '+(user.done.length*50+(user.arenaXP||0))+' XP':'Profil pemain';main.replaceChildren();({studio,home,karakter,skin:wardrobe,map:mapView,quest:journal,arena:arenaView})[current]();let el=document.createElement('p');el.id='notice';el.setAttribute('role','status');main.append(el)}
function home(){main.innerHTML='<section class="homeHero"><div><span class="label">ATLAS NAHWU</span><h1>Desa Alif</h1><p>Jelajahi wilayah Atlas, pecahkan misi bahasa Arab, dan buka pakaian baru untuk karaktermu.</p><b class="tagline">ATLAS BAHASA ARAB</b></div></section><div class="twocol"><section class="box" id="login"></section><section class="box" id="continue"></section></div>';
 const area=$('login'),side=$('continue');if(!user){authHome(area,side);return}
 document.querySelector('.tagline').textContent=worlds.length+' WILAYAH · '+lessons.length+' QUEST · 12 SKIN';
 area.append(heading('h2','Selamat datang, '+user.name),heading('p',user.done.length+' dari '+lessons.length+' quest selesai'),btn('Jelajahi map →',()=>go('map'),'gold'),btn('Masuk lobi',()=>go('arena')),btn('Keluar akun',logout));
 if(isTeacher)area.append(btn('Buka Studio Guru',()=>go('studio')));
 side.append(heading('h2','Lanjutkan quest'));const id=Object.keys(user.steps).map(Number).find(i=>user.steps[i]>0)??lessons.findIndex((a,i)=>!user.done.includes(i));if(id>=0)side.append(heading('p',lessons[id][0]+' · '+worlds.find(w=>w.quests.some(q=>q.id===id)).title),btn('Buka quest',()=>lesson(id)));else side.append(heading('p','Semua quest telah selesai. Kamu bisa mengulang latihan melalui jurnal.'))}
function karakter(){main.innerHTML='<span class="label">PROFIL PEMAIN</span><h1>Tampilan Karakter</h1><div class="twocol"><section class="bigSkin" id="look"></section><section class="box"><h2>Nama karakter</h2><p>Nama ini tampil di atas karaktermu saat menjelajah.</p><form id="rename"><label>Nama panggilan<br><input id="newName" required maxlength="24"></label><button class="gold">Simpan nama</button></form></section></div>';
 $('look').append(portrait(user.skin),heading('h2',user.name),heading('p',outfits[user.skin]),heading('p','Rank arena · '+(user.arenaRank||'Perunggu')+' · '+(user.arenaRP||0)+' RP'),btn('Ganti skin',()=>go('skin')));$('newName').value=user.name;
 $('look').append(heading('small','ID akun · '+user.id));
 $('rename').onsubmit=async e=>{e.preventDefault();if(await save(p=>p.name=$('newName').value.trim())){render();message('Nama karakter berhasil disimpan.')}}}
function wardrobe(){main.innerHTML='<span class="label">INVENTARIS</span><h1>Koleksi Skin</h1><p>Pilih pakaian yang sudah terbuka untuk memakainya di semua wilayah.</p><div class="cards" id="skins"></div>';outfits.forEach((s,i)=>{const b=btn('',async()=>{if(await save(p=>{if(gates[i]<=p.done.length)p.skin=i})){render();message('Skin berhasil dipakai.')}},'skinButton');const body=document.createElement('div');body.append(heading('h3',s),heading('small',i===user.skin?'✓ Dipakai':gates[i]>user.done.length?'Terkunci · '+gates[i]+' quest':'Pakai skin'));b.disabled=i===user.skin||gates[i]>user.done.length;b.append(portrait(i),body);$('skins').append(b)})}
function status(i){return user.steps[i]?'Lanjut · soal '+(user.steps[i]+1)+'/'+bank[i].length:user.done.includes(i)?'✓ Selesai · ulangi':bank[i].length+' soal · 50 XP'}
function questCard(i,j){const b=btn('',()=>lesson(i),'card');b.append(heading('small','POS '+(j+1)),heading('h3',lessons[i][0]),heading('small',status(i)));return b}
function nearest(){return spots.reduce((a,x,j)=>Math.abs(spots[a]-pos)<=Math.abs(x-pos)?a:j,0)}
function walk(v){pos=Math.max(8,Math.min(92,v));$('player').style.left=pos+'%';$('start').textContent='Masuk pos '+(nearest()+1)+' →'}
function mapView(){main.innerHTML='<span class="label">ATLAS NAHWU</span><h1>Map</h1><nav class="atlas" id="atlas" aria-label="Pilih wilayah"></nav><section class="world"><canvas id="land" width="480" height="128"></canvas><span class="label" id="region"></span><h1 id="title"></h1><div id="pins"></div><div id="player" class="player"><span class="name" id="tag"></span></div></section><div id="walk" class="tools"></div><h2 id="theme"></h2><p>Pilih pos di peta atau gerakkan karakter dengan tombol panah.</p><div class="cards" id="cards"></div>';
 let w=user.world, world=worlds[w];worlds.forEach((m,k)=>{let b=btn((k+1)+'. '+m.title,async()=>{if(await save(p=>p.world=k)){pos=18;render()}});b.setAttribute('aria-current',k===w);$('atlas').append(b)});
 $('region').textContent='WILAYAH '+(w+1);$('title').textContent=world.title;$('theme').textContent=world.theme;$('tag').textContent=user.name;$('player').append(portrait(user.skin));landscape(w%6);
 spots=world.quests.map((q,j)=>world.quests.length===1?50:18+64*j/(world.quests.length-1));
 world.quests.forEach(({id},j)=>{const b=btn((user.done.includes(id)?'✓ ':'⚑ ')+(j+1),()=>walk(spots[j]),'pin');b.style.left=spots[j]+'%';b.setAttribute('aria-label','Ke pos '+(j+1)+' '+lessons[id][0]);$('pins').append(b);$('cards').append(questCard(id,j))});
 if(!spots.length){$('walk').textContent='Guru belum menambahkan quest di wilayah ini.';return}
 const start=btn('',()=>lesson(world.quests[nearest()].id),'gold');start.id='start';$('walk').append(btn('← Kiri',()=>walk(pos-8)),btn('Kanan →',()=>walk(pos+8)),start);walk(pos)}
function journal(){main.innerHTML='<span class="label">JURNAL PEMAIN</span><h1>Quest &amp; Achievement</h1><h2 class="section">Pencapaian</h2><div id="badges"></div><h2 class="section">Daftar quest</h2>';const d=user.done;const stats=[['Langkah Pertama',d.length,1,'quest'],['Penjelajah Atlas',worlds.filter(m=>m.quests.length&&m.quests.every(q=>d.includes(q.id))).length,worlds.length,'wilayah tuntas'],['Kolektor Skin',gates.filter(g=>g<=d.length).length,12,'skin'],['Ahli Nahwu',d.length,lessons.length,'quest']];for(const [name,n,max,unit] of stats){let el=document.createElement('div');el.className='achievement';el.append(heading('strong',(n>=max?'★ ':'☆ ')+name),heading('small',Math.min(n,max)+' / '+max+' '+unit));$('badges').append(el)}
 worlds.forEach(m=>{main.append(heading('h3',m.title));let g=document.createElement('div');g.className='cards questrow';m.quests.forEach((q,j)=>g.append(questCard(q.id,j)));main.append(g)})}
function lesson(i){const a=lessons[i];show(a[0]);let example=document.createElement('div');example.className='example';let arab=heading('b',a[1]);arab.className='ar';arab.lang='ar';arab.dir='rtl';example.append(arab,heading('span',a[2]));if(a[1]||a[2])panel.append(example);if(a[3])panel.append(heading('h3','Cara membacanya'),heading('p',a[3]));if(a[4])panel.append(heading('h3','Perhatikan'),heading('p',a[4]));panel.append(btn(user.steps[i]?'Lanjut ke soal '+(user.steps[i]+1):'Mulai latihan · '+bank[i].length+' soal',()=>quiz(i),'gold'))}
function quiz(i){const n=user.steps[i]||0,[q,correct,...rest]=bank[i][n];show(lessons[i][0]);panel.append(heading('small','SOAL '+(n+1)+' / '+bank[i].length),heading('h3',q));let choices=document.createElement('div');choices.className='choices';let note=heading('p','');note.setAttribute('role','status');panel.append(choices,note);let opts=[correct,...rest.slice(0,2)];for(let j=2;j>0;j--){let k=Math.floor(Math.random()*(j+1));[opts[j],opts[k]]=[opts[k],opts[j]]}
 opts.forEach(x=>{let b=btn(x,async()=>{if(x!==correct){b.disabled=true;note.textContent='Belum tepat. '+rest[2]+' Coba lagi.';return}
 const before=user.done.length;if(!await save(p=>{if((p.steps[i]||0)!==n)return;if(n+1<bank[i].length)p.steps[i]=n+1;else{delete p.steps[i];if(!p.done.includes(i))p.done.push(i)}}))return;
 for(const opt of choices.children)opt.disabled=true;note.textContent='Benar! '+rest[2];render();panel.append(btn(n+1<bank[i].length?'Soal berikutnya →':'Lihat hasil →',()=>n+1<bank[i].length?quiz(i):result(i,user.done.length>before),'gold'))});choices.append(b)})}
function result(i,fresh){show('Quest selesai');panel.append(heading('p',lessons[i][0]+' · '+bank[i].length+' soal selesai.'),heading('h3',fresh?'+50 XP':'Latihan ulang selesai'));let reward=fresh?gates.indexOf(user.done.length):-1;if(reward>=0)panel.append(heading('p','Skin baru terbuka: '+outfits[reward]),btn('Lihat skin',()=>{dialog.close();go('skin')}));panel.append(btn('Kembali',()=>dialog.close(),'gold'))}
$('cross').onclick=()=>dialog.close();window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render()});
document.addEventListener('keydown',e=>{if(view()==='map'&&spots.length&&!dialog.open&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();walk(pos+(e.key==='ArrowLeft'?-8:8))}});
boot();
